from rich.console import Console

def test_record_export_after_disable():
    console = Console(record=True)
    console.print("Hello World")
    console.record = False
    # This should not raise AssertionError
    text = console.export_text()
    assert text == "Hello World\n"

def test_record_export_no_record_no_buffer():
    console = Console(record=False)
    try:
        console.export_text()
    except AssertionError:
        return
    # Should have raised AssertionError if no recording was ever enabled and buffer is empty
    raise AssertionError("Should have raised AssertionError when record=False and buffer is empty")

if __name__ == "__main__":
    try:
        test_record_export_after_disable()
        print("test_record_export_after_disable passed")
    except Exception as e:
        print(f"test_record_export_after_disable failed: {e}")
        exit(1)

    try:
        test_record_export_no_record_no_buffer()
        print("test_record_export_no_record_no_buffer passed")
    except Exception as e:
        print(f"test_record_export_no_record_no_buffer failed: {e}")
